+++ b/tests/stock.test.js
@@ -27,3 +27,28 @@ test("waste is recorded against a batch", () => {
   assert.equal(m.type, "waste");
   assert.equal(store.data.batches.find((b) => b.id === 6).qty, 12);
 });
+
+test("consume uses the batch that expires first (FEFO)", () => {
+  const store = fresh();
+  // Milk: lot HD-1022 (batch 4) expires before the newer lot HD-1026 (batch 3).
+  assert.deepEqual(consume(store, 2, 1, { at }), [{ batchId: 4, qty: 1 }]);
+  // Running past the first batch spills into the next one to expire.
+  assert.deepEqual(consume(store, 2, 2, { at }), [
+    { batchId: 4, qty: 1 },
+    { batchId: 3, qty: 1 },
+  ]);
+});
+
+test("consume uses batches without expiry last, then received date, then id", () => {
+  const store = fresh();
+  const batch = (id, receivedOn, expires) => ({ id, itemId: 4, lot: `T-${id}`, qty: 1, receivedOn, expires, location: "dry" });
+  store.data.batches = [
+    batch(101, "2026-10-01", null),
+    batch(102, "2026-10-05", "2026-12-01"),
+    batch(103, "2026-10-03", "2026-12-01"),
+    batch(104, "2026-10-03", "2026-12-01"),
+    batch(105, "2026-10-20", "2026-11-15"),
+  ];
+  const used = consume(store, 4, 5, { at });
+  assert.deepEqual(used.map((u) => u.batchId), [105, 103, 104, 102, 101]);
+});
